func TestBhvSerializationparam033_ValueSerializer_EmptyStringPathParamIsMissingRequiredParameter(t *testing.T) {
	t.Parallel()
	// Gap W — empty-string path values silently produce malformed
	// URLs like `/resource//details`; reject them before the request is
	// built so callers see the real error rather than a downstream 404.
	// A caller mistake is a returned sentinel, never a panic.
	type color string
	var nilString *string
	for _, value := range []any{"", color(""), nilString, nil} {
		err := requirePathParam("id", value)
		if !errors.Is(err, ErrMissingRequiredParameter) {
			t.Errorf("expected ErrMissingRequiredParameter for %#v, got %v", value, err)
		}
		var root pkgerrors.OpenAPIError
		if errors.As(err, &root) {
			t.Errorf("a caller mistake must not be a OpenAPIError, got %T", err)
		}
	}
	if err := requirePathParam("id", "5"); err != nil {
		t.Errorf("expected no error for a non-empty path param, got %v", err)
	}
}

func TestBhvSerializationparam029_ValueSerializer_DotSegmentPathParamIsInvalidPathParameter(t *testing.T) {
	t.Parallel()
	type label string
	for _, value := range []any{".", "..", label("..")} {
		err := requirePathParam("name", value)
		if !errors.Is(err, ErrInvalidPathParameter) {
			t.Errorf("expected ErrInvalidPathParameter for %#v, got %v", value, err)
		}
		if err == nil || !strings.HasSuffix(err.Error(), "path parameter 'name' must not be '.' or '..'") {
			t.Errorf("unexpected message for %#v: %v", value, err)
		}
	}
	for _, value := range []any{"a..b", ".hidden", "..."} {
		if err := requirePathParam("name", value); err != nil {
			t.Errorf("expected no error for %q, got %v", value, err)
		}
	}
}

// ── N3/W3 parity: format:date path parameter emits YYYY-MM-DD ──
//
// Go has only time.Time (no separate date-only type), so the codegen
// routes `format: date` path params through StringifyDate to strip the
// time component. Without this, a date param would go out as a full
// ISO+offset string, mismatching the 6 SDKs (Java/Kotlin/C#/Python/
// Ruby/Elixir) with native LocalDate types.

func TestBhvSerializationparam054_ValueSerializer_FormatDatePathParam_TimeReturnsDateOnly(t *testing.T) {
	t.Parallel()
	when := time.Date(2024, time.January, 15, 14, 30, 45, 0, time.UTC)
	if got := stringifyDate(when); got != "2024-01-15" {
		t.Errorf("expected '2024-01-15', got %q", got)
	}
}

